<?php
require_once __DIR__ . '/includes/auth.php'; requireLogin(); $userId=(int)$_SESSION['user_id']; $team=getTeamStats($userId); $level=(int)($_GET['level'] ?? 0); if($level<1||$level>3)$level=null; $members=getUserReferrals($userId,$level); $pageTitle='My Team';
if (isset($_GET['ajax'])) { header('Content-Type: application/json'); ob_start(); if(!$members) echo '<p class="empty">No members in this level yet.</p>'; else { echo '<div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Level</th><th>Joined</th></tr></thead><tbody>'; foreach($members as $m) echo '<tr><td>'.e($m['name']).'</td><td>'.e($m['username']).'</td><td>L'.(int)$m['level'].'</td><td>'.e(formatDate($m['created_at'])).'</td></tr>'; echo '</tbody></table></div>'; } echo json_encode(['html'=>ob_get_clean()]); exit; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/includes/header.php'; ?><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main-content"><div class="page-title"><span class="eyebrow">NETWORK PERFORMANCE</span><h1>My team</h1><p class="muted">Track members connected through your referral network.</p></div><div class="stat-grid"><div class="stat-card"><span>Level 1</span><strong><?= e($team['level1_count']) ?></strong><i class="fas fa-user-plus"></i></div><div class="stat-card"><span>Level 2</span><strong><?= e($team['level2_count']) ?></strong><i class="fas fa-user-group"></i></div><div class="stat-card"><span>Level 3</span><strong><?= e($team['level3_count']) ?></strong><i class="fas fa-network-wired"></i></div><div class="stat-card"><span>Team volume</span><strong><?= formatCurrency($team['total_volume']) ?></strong><i class="fas fa-chart-column"></i></div></div><section class="panel"><div class="tabs"><a class="<?= $level===null?'active':'' ?>" href="team.php">All members</a><a class="<?= $level===1?'active':'' ?>" href="team.php?level=1">Level 1</a><a class="<?= $level===2?'active':'' ?>" href="team.php?level=2">Level 2</a><a class="<?= $level===3?'active':'' ?>" href="team.php?level=3">Level 3</a></div><div id="memberDirectory"><?php if(!$members): ?><p class="empty">No members in this view yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Level</th><th>Joined</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><?= e($m['name']) ?></td><td><?= e($m['username']) ?></td><td><span class="badge active">L<?= e($m['level']) ?></span></td><td><?= e(formatDate($m['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section></main><?php include __DIR__.'/includes/bottom-nav.php'; ?><?php include __DIR__.'/includes/footer.php'; ?><script src="assets/js/app.js"></script></body></html>
